// ------------------------------------------------------------- Werkzeug

const arg = (name) => {
  const i = process.argv.indexOf(name);
  return i >= 0 ? process.argv[i + 1] : null;
};
const mitAlt = process.argv.includes("--alt");
// --zeig: je Sabotage alle roten Proben ausgeben. Fuer den Bau neuer Sabotagen.
const zeig = process.argv.includes("--zeig");
const nurSatz = arg("--satz");

// Die Ersetzung steht seit stre-T-015 in `tools/lib/ersetze.mjs`, weil der
// Bench-Laeufer dieselbe braucht.
const liegtImBaum = (datei) => existsSync(join(WURZEL, datei));

// Die laufenden Satzprozesse. Der Signalweg beendet sie vor dem Abraeumen,
// sonst haelt unter Windows ihr Arbeitsordner die Kopie fest (EBUSY).
const kinder = new Set();

/*
 * DER LAUF STEHT SEIT stre-T-126 IN `tools/lib/kindlauf.mjs`. Vorher stand er
 * hier, setzte `rc: fehler.code ?? 1` und verwarf stderr: ein Absturz und eine
 * Toetung an der Zeitgrenze hiessen beide "rc 1 ohne rote Probe". Jetzt kommt
 * jeder Ausgang mit Art und Erklaerung zurueck, und eine Toetung zaehlt als
 * nicht pruefbar, nie als bewacht.
 */
//
// `--zeitgrenze <ms>` gilt fuer die Sabotagelaeufe und fuer `--alle-saetze`,
// der Grundlauf behaelt 120 s. Sie ist die Probe dafuer, dass eine Toetung
// als nicht pruefbar endet: mit `--zeitgrenze 1` waere sonst schon der
// Grundlauf getoetet, und der Weg mit S-Nummer liefe nie. `--alle-saetze`
// hat keinen Grundlauf; ohne die Grenze war sein Weg bei einer Toetung
// nicht erreichbar und rc 2 dort nur gelesen (stre-T-126 Nachtrag).
const zeitgrenze = Number(arg("--zeitgrenze") ?? ZEITGRENZE_MS);
// execFile setzt bei 0 keinen Zeitgeber und wirft bei NaN oder Bruch erst im
// ersten Sabotagelauf. Beides wuerde die Probe still entwerten.
if (!Number.isInteger(zeitgrenze) || zeitgrenze < 1) {
  console.log("NICHT PRUEFBAR: --zeitgrenze braucht ganze Millisekunden ab 1.");
  process.exit(2);
}
function fahre(verzeichnis, datei, grenze = ZEITGRENZE_MS) {
  return fahreKind(verzeichnis, datei, { zeitgrenze: grenze, kinder });
}

function kopiere(ziel) {
  // css seit stre-T-164: der Satz unterpfad liest die Stilblaetter.
  for (const teil of ["scripts", "lang", "ui", "tools", "templates", "css"]) {
    cpSync(join(WURZEL, teil), join(ziel, teil), { recursive: true });
  }
  for (const datei of ["module.json", "package.json"]) {
    if (existsSync(join(WURZEL, datei))) cpSync(join(WURZEL, datei), join(ziel, datei));
  }
}

// ------------------------------------------------------------- --alle-saetze

// Die Vertragssaetze (stre-T-021), deren Rueckgabe 2 "Nachbar fehlt" heisst.
const VERTRAGSSATZ = /(^|\/)stream-vertrag-[^/]+\.test\.mjs$/;

if (process.argv.includes("--alle-saetze")) {
  const saetze = [];
  for (const ordner of ["scripts/stream", "scripts/loot"]) {
    for (const n of readdirSync(join(WURZEL, ordner)).sort()) {
      if (n.endsWith(".test.mjs")) saetze.push(`${ordner}/${n}`);
    }
  }
  let schlecht = 0;
  let getoetet = 0;
  let nichtGemessen = 0;
  for (const s of saetze) {
    const r = await fahre(WURZEL, s, zeitgrenze);
    // Rueckgabe 2 eines Vertragssatzes heisst nicht gemessen (Nachbarklon
    // fehlt, stre-T-021): nie ein Befund, aber auch nie gruen. Wie im Haken
    // gilt das NUR fuer stream-vertrag-*; jeder andere Satz mit 2 ist schlecht.
    const ungemessen = r.rc === 2 && !r.getoetet && VERTRAGSSATZ.test(s);
    if (ungemessen) nichtGemessen += 1;
    else if (r.rc !== 0 || r.getoetet) schlecht += 1;
    if (r.getoetet) getoetet += 1;
    const warum = ungemessen
      ? ` nicht gemessen: ${r.ausgabe.filter((z) => z.includes("NICHT GEMESSEN")).slice(-1)[0] || erklaere(r, zeitgrenze)}`
      : ["absturz", "zeitgrenze"].includes(einordnen(r)) ? ` ${einordnen(r)}: ${erklaere(r, zeitgrenze)}` : "";
    console.log(`${s} rc=${r.rc} ok=${r.gruen.size} rot=${r.rot.size}${warum}`);
  }
  console.log(`saetze=${saetze.length}, davon rot oder abgebrochen: ${schlecht}, nicht gemessen: ${nichtGemessen}`);
  if (schlecht === 0 && nichtGemessen > 0) process.exit(2);
  // Eine Untergrenze wie im Haken: ein neuer Satz bricht die Zahl nicht.
  // Eine Toetung ist nicht pruefbar (2), wie im Sabotageweg, nie ein Befund.
  if (getoetet > 0) process.exit(2);
  process.exit(saetze.length >= 12 && schlecht === 0 ? 0 : 1);
}

// ------------------------------------------------------------- Lauf

// NUR AUF ZURUF (Nachtrag stre-T-157): `doppelwache` faehrt den Vorhaken in
// eigenen Kopien, hoechstens zwei zugleich, und braucht allein gemessen 204 s,
// neben anderer Last 459 s. Im vollen Lauf kaeme das je Sabotage dazu, mit
// vier Kopien zugleich ueber eine Stunde. Er laeuft mit `--satz doppelwache`
// und im Vorhaken, sobald tools/haken oder einer der Bench-Ordner vorgemerkt ist.
// `vertrag-manifest` (stre-T-021) liest die Vorlagen per git show aus zwei
// Nachbarklonen und ist ohne sie nicht messbar; der Vorgabelauf soll daran
// nicht haengen. Er laeuft mit `--satz vertrag-manifest`. Ebenso
// `vertrag-adresse` (stre-T-021): er holt das Tor per git show aus dem Worker.
// vorpush (stre-T-028) pusht je Sabotage in Wegwerfdepots und braucht allein
// ein Vielfaches eines anderen Satzes. Der Satz selbst laeuft im Vorhaken,
// sobald der Push-Riegel oder module.json vorgemerkt ist; seine Sabotagen auf
// Zuruf mit --satz vorpush.
// betreffkennung (stre-T-047) macht je Sabotage echte Commits in Wegwerfdepots,
// allein gemessen 271 s fuer 55 Sabotagen. Der Satz selbst laeuft im Vorhaken,
// sobald der Kennungsriegel oder module.json vorgemerkt ist; seine Sabotagen auf
// Zuruf mit --satz betreffkennung.
const NUR_AUF_ZURUF = ["doppelwache", "vorpush", "vertrag-manifest", "vertrag-adresse", "betreffkennung"];
const SAETZE = ["maske", "geteilt", "bilder", "ersatzbild", "posen", "beute", "weiche", "blatt", "bonustab", "heilung", "leinwand", "basis", "umschalter", "einbau", "klang", "html", "hakenfehler", "rueckfall", "fremdflaggen", "flaggen", "export", "kaufknopf", "zusage", "kennung", "riegel", "sperre", "platzhalter", "kodexreiter", "unterpfad", "hinweis", "klangwache", "vorrat", "traeger", "traeger-ersatz", "pruefsumme", "offline-geteilt", "betazip", "betreffkennung", "vorpush", "doppelwache", "vertrag-manifest", "vertrag-adresse"]
  .filter((s) => (nurSatz ? s === nurSatz : !NUR_AUF_ZURUF.includes(s)));
if (!nurSatz) console.log(`nur auf Zuruf, nicht in diesem Lauf: ${NUR_AUF_ZURUF.join(", ")}`);
if (SAETZE.length === 0) {
  console.log(`unbekannter Satz: ${nurSatz}`);
  process.exit(2);
}

/*
 * EIN SATZ, DEN ES AN DER BASIS NOCH NICHT GAB (seit stre-T-113 `bonustab`),
 * hat keinen alten Stand. `git show` wuerfe dort und braeche den Lauf mit
 * `--alt` ab. Die Altkopie laesst ihn aus; seine Sabotagen tragen kein `luecke`.
 */
const basisBekannt = new Map();
function mitBasis(satz) {
  if (!basisBekannt.has(satz)) {
    let da = true;
    try {
      execFileSync("git", ["-C", WURZEL, "cat-file", "-e", `${BASIS}:${SATZDATEI(satz)}`], { stdio: "ignore" });
    } catch {
      da = false;
    }
    basisBekannt.set(satz, da);
  }
  return basisBekannt.get(satz);
}

const PARALLEL = 4;
const kopienNeu = [];
const kopienAlt = [];
let befund = 0;
let nichtPruefbar = 0;
const t0 = Date.now();

// Jede Kopie einzeln: ein EBUSY unter Windows darf die anderen nicht liegen
// lassen. Was bleibt, wird genannt. Zweimal gerufen schadet nicht.
function raeumeAb() {
  for (const d of [...kopienNeu, ...kopienAlt]) {
    try {
      rmSync(d, { recursive: true, force: true, maxRetries: 10, retryDelay: 200 });
    } catch (e) {
      // Windows meldet EBUSY auch dann, wenn das Verzeichnis nur noch zum
      // Loeschen vorgemerkt ist und gleich verschwindet; genannt wird nur,
      // was danach wirklich noch liegt.
      if (existsSync(d)) console.log(`REST nicht abgeraeumt: ${d} (${e && e.code})`);
    }
  }
}
// Ein Abbruch per Strg+C oder SIGTERM ueberspringt `finally`; ohne diese zwei
// Zeilen blieben bis zu acht Kopien von je rund 13 MB im Temp-Verzeichnis
// (Kaltdurchsicht 15.11.2026).
async function abbrechen(rc) {
  const enden = [...kinder].map((k) => new Promise((fertig) => {
    k.once("exit", fertig);
    k.kill();
  }));
  // Ein Kind, das nicht endet, haelt den Abbruch nicht auf.
  await Promise.race([Promise.all(enden), new Promise((r) => setTimeout(r, 3000))]);
  raeumeAb();
  process.exit(rc);
}
process.once("SIGINT", () => { abbrechen(130); });
process.once("SIGTERM", () => { abbrechen(143); });

// Ein rotes Ergebnis verlaesst den Lauf mit `break lauf`, nie mit
// process.exit: das wuerde `finally` ueberspringen und Kopien liegen lassen.
lauf: try {
  // 0. Die Kopien. Jede steht in ihrer Liste, sobald sie angelegt ist, damit
  // `finally` sie auch dann abraeumt, wenn das Kopieren selbst wirft.
  for (let i = 0; i < PARALLEL; i += 1) {
    const d = mkdtempSync(join(tmpdir(), "stream-sabotage-"));
    kopienNeu.push(d);
    kopiere(d);
  }
  if (mitAlt) {
    /*
     * DER ALTE SATZ GEHOERT ZUM ALTEN CODE. Die zwei Naehte aendern Text, den
     * die alten Saetze als Text lesen (gemessen 15.11.2026: der alte
     * stream-geteilt schneidet `vorratsSchluessel` aus dem Quelltext und wird
     * am Nahtstand ohne Sabotage rot). Also liegen die Nahtdateien in der
     * Altkopie im Stand der Basis.
     */
    for (const datei of NAEHTE) {
      basisText[datei] = execFileSync("git", ["-C", WURZEL, "show", `${BASIS}:${datei}`], { encoding: "utf8" });
    }
    for (let i = 0; i < PARALLEL; i += 1) {
      const d = mkdtempSync(join(tmpdir(), "stream-sabotage-alt-"));
      kopienAlt.push(d);
      kopiere(d);
      for (const satz of SAETZE) {
        if (!mitBasis(satz)) continue;
        const alt = execFileSync("git", ["-C", WURZEL, "show", `${BASIS}:${SATZDATEI(satz)}`]);
        writeFileSync(join(d, SATZDATEI(satz)), alt);
      }
      for (const datei of NAEHTE) writeFileSync(join(d, datei), basisText[datei]);
    }
  }

  // 1. Ohne Sabotage gruen, und die Probenliste je Satz.
  const proben = {};
  for (const satz of SAETZE) {
    const r = await fahre(kopienNeu[0], SATZDATEI(satz), GRENZE_SATZ[satz] ?? ZEITGRENZE_MS);
    proben[satz] = r.gruen;
    // Zwei Proben mit einem Namen sind fuer die Deckung eine: wird nur eine rot,
    // gaelten beide als bewacht (Kaltdurchsicht 15.11.2026, maske).
    if (r.doppelt.size > 0) {
      console.log(`NICHT PRUEFBAR: ${satz} traegt doppelte Probennamen: ${[...r.doppelt].join(" | ")}`);
      nichtPruefbar += 1;
    }
    if (r.rc !== 0 || r.rot.size > 0 || r.getoetet) {
      const art = einordnen(r);
      // Rueckgabe 2 ohne Toetung: der Satz sagt selbst, warum (NICHT GEMESSEN
      // auf stdout, etwa ein fehlender Nachbarklon); das gehoert in die Zeile.
      const selbst = r.rc === 2 && !r.getoetet ? r.ausgabe.slice(-1)[0] : "";
      const warum = art === "rot" ? `${r.rot.size} rot` : `${art}: ${erklaere(r)}${selbst ? `; ${selbst}` : ""}`;
      console.log(`NICHT PRUEFBAR: ${satz} ist schon ohne Sabotage nicht gruen (${warum}).`);
      nichtPruefbar += 1;
    }
    if (mitAlt && mitBasis(satz)) {
      const a = await fahre(kopienAlt[0], SATZDATEI(satz));
      if (a.rc !== 0 || a.getoetet) {
        console.log(`NICHT PRUEFBAR: der alte Satz ${satz} ist schon ohne Sabotage nicht gruen (${einordnen(a)}: ${erklaere(a)}).`);
        nichtPruefbar += 1;
      }
    }
  }
  if (nichtPruefbar > 0) break lauf;

  // 2. Die Sabotagen, verteilt auf die Kopien.
  const auftraege = SABOTAGEN.map((s, nr) => ({ ...s, nr: nr + 1 })).filter((s) => SAETZE.includes(s.satz));
  const ergebnisse = [];
  let naechster = 0;
  const lies = (datei) => readFileSync(join(WURZEL, datei), "utf8");
  const liesAlt = (datei) => (datei in basisText ? basisText[datei] : lies(datei));
  async function arbeiter(i) {
    while (naechster < auftraege.length) {
      const s = auftraege[naechster];
      naechster += 1;
      const e = ersetze(lies, s.ersetze, liegtImBaum);
      if (e.fehler) { ergebnisse.push({ s, fehler: e.fehler }); continue; }
      for (const [datei, text] of e.neu) writeFileSync(join(kopienNeu[i], datei), text);
      const r = await fahre(kopienNeu[i], SATZDATEI(s.satz), grenzeFuer(s.satz, zeitgrenze));
      for (const datei of e.neu.keys()) {
        if (existsSync(join(WURZEL, datei))) writeFileSync(join(kopienNeu[i], datei), lies(datei));
        else rmSync(join(kopienNeu[i], datei), { force: true });
      }
      // Der alte Satz bekommt dieselbe Sabotage, angewandt auf SEINEN Stand der
      // Nahtdateien. Fehlt der Anker dort, ist die Luecke nicht belegbar.
      let a = null;
      if (mitAlt && s.luecke) {
        const ea = ersetze(liesAlt, s.ersetze, liegtImBaum);
        if (ea.fehler) a = { fehlerAlt: ea.fehler };
        else {
          for (const [datei, text] of ea.neu) writeFileSync(join(kopienAlt[i], datei), text);
          a = await fahre(kopienAlt[i], SATZDATEI(s.satz), zeitgrenze);
          for (const datei of ea.neu.keys()) {
            if (existsSync(join(WURZEL, datei))) writeFileSync(join(kopienAlt[i], datei), liesAlt(datei));
            else rmSync(join(kopienAlt[i], datei), { force: true });
          }
        }
      }
      ergebnisse.push({ s, r, a });
    }
  }
  await Promise.all(kopienNeu.map((_, i) => arbeiter(i)));
  ergebnisse.sort((x, y) => x.s.nr - y.s.nr);

  const bewacht = Object.fromEntries(SAETZE.map((s) => [s, new Set()]));
  const altGruen = Object.fromEntries(SAETZE.map((s) => [s, 0]));
  const luecken = Object.fromEntries(SAETZE.map((s) => [s, 0]));
  // Ziele einer getoeteten Sabotage: ungemessen, also weder bewacht noch
  // unbewacht (stre-T-126 Nachtrag, orch 17.11.2026).
  const getoetetZiele = Object.fromEntries(SAETZE.map((s) => [s, new Set()]));
  for (const { s, fehler, r, a } of ergebnisse) {
    const kopf = `S${String(s.nr).padStart(3, "0")} ${s.satz}`;
    if (fehler) {
      console.log(`  NICHT PRUEFBAR ${kopf}: ${fehler}`);
      nichtPruefbar += 1;
      continue;
    }
    if (zeig) console.log(`  ${kopf} rc ${r.rc} rot: ${[...r.rot].join(" | ")}`);
    // AN DER ZEITGRENZE GETOETET IST NICHT GEMESSEN (stre-T-126). Was der
    // Prozess bis dahin gedruckt hat, ist kein Ergebnis: seine Ziele zaehlen
    // nicht als bewacht, und der Lauf endet mit rc 2, nie gruen.
    if (r.getoetet) {
      nichtPruefbar += 1;
      for (const n of s.ziel) getoetetZiele[s.satz].add(n);
      console.log(`  NICHT PRUEFBAR ${kopf}: ${erklaere(r, zeitgrenze)}`);
      continue;
    }
    // Ein Ziel muss eine Probe des ungestoerten Satzes sein. Traegt ein
    // Probenname einen Wert, den die Sabotage aendert, heisst die rote Probe
    // anders als die gruene, und das Ziel bewachte nichts.
    const fremdeZiele = s.ziel.filter((n) => !proben[s.satz].has(n));
    if (fremdeZiele.length > 0) {
      befund += 1;
      console.log(`  BEFUND ${kopf}: Ziel ist keine Probe des Satzes: ${fremdeZiele.join(" | ")}`);
    }
    // Ein Satz, der abbricht, ohne eine Probe rot zu melden, zeigt keine
    // Wirkung, sondern einen Absturz (gemessen an stream-geteilt, 14.11.2026:
    // `.match(...).length` auf null).
    // Seit stre-T-126 mit dem, was der Prozess auf stderr gesagt hat.
    if (einordnen(r) === "absturz") {
      befund += 1;
      console.log(`  BEFUND ${kopf}: ohne rote Probe abgebrochen, ${erklaere(r, zeitgrenze)}`);
    }
    for (const n of s.ziel) if (r.rot.has(n) && proben[s.satz].has(n)) bewacht[s.satz].add(n);
    const verfehlt = s.ziel.filter((z) => !r.rot.has(z));
    if (r.rc === 0 || verfehlt.length > 0) {
      befund += 1;
      console.log(`  BEFUND ${kopf}: rc ${r.rc}, Ziel nicht rot: ${verfehlt.join(" | ") || "(rc 0)"}`);
    }
    if (a && a.fehlerAlt) {
      luecken[s.satz] += 1;
      nichtPruefbar += 1;
      console.log(`  NICHT PRUEFBAR ${kopf}: im alten Stand ${a.fehlerAlt}`);
    } else if (a && a.getoetet) {
      luecken[s.satz] += 1;
      nichtPruefbar += 1;
      console.log(`  NICHT PRUEFBAR ${kopf}: im alten Stand ${erklaere(a, zeitgrenze)}`);
    } else if (a) {
      luecken[s.satz] += 1;
      if (a.rc === 0) altGruen[s.satz] += 1;
      else {
        befund += 1;
        console.log(`  BEFUND ${kopf}: als Luecke markiert, aber der alte Satz wird rot (${[...a.rot].slice(0, 2).join(" | ")})`);
      }
    }
  }

  // 3. Jede Probe als Ziel einer Sabotage rot.
  console.log("");
  for (const satz of SAETZE) {
    const eigen = EIGENPROBEN[satz] || {};
    const alle = [...proben[satz]];
    const offen = alle.filter((n) => !bewacht[satz].has(n) && !(n in eigen));
    // Eine Toetung sagt nichts ueber die Bewachung: ihre Ziele sind nicht
    // pruefbar und kein Befund. Die Toetung selbst steht schon in nichtPruefbar.
    const ungemessen = offen.filter((n) => getoetetZiele[satz].has(n));
    const unbewacht = offen.filter((n) => !getoetetZiele[satz].has(n));
    const art = (p) => alle.filter((n) => n.startsWith(p)).length;
    const zahlSab = auftraege.filter((s) => s.satz === satz).length;
    const alt = mitAlt ? `, alt gruen ${altGruen[satz]} von ${luecken[satz]} Luecken` : "";
    console.log(`${satz}: ${alle.length} Proben (Struktur ${art("[Struktur] ")}, Dokument ${art("[Dokument] ")}), `
      + `${bewacht[satz].size} per Sabotage rot belegt, ${Object.keys(eigen).length} Eigenprobe(n), `
      + `${unbewacht.length} unbewacht, ${zahlSab} Sabotagen${alt}`);
    for (const n of ungemessen) console.log(`  NICHT PRUEFBAR ${n}: Ziel einer getoeteten Sabotage`);
    for (const n of unbewacht) {
      befund += 1;
      console.log(`  UNBEWACHT ${n}`);
    }
  }
} finally {
  raeumeAb();
}

console.log(`\n${((Date.now() - t0) / 1000).toFixed(1)} s, Befunde ${befund}, nicht pruefbar ${nichtPruefbar}`);
process.exit(nichtPruefbar > 0 ? 2 : (befund > 0 ? 1 : 0));
